#!/bin/bash
# S4 (network on; image = after S1): kernel image 7.0.0-42 installed WITHOUT its headers (the
# metapackage normally brings them in a separate dpkg step), then the headers arrive.
# Expect: first hook -> pending-headers + pin to 38; headers hook -> build, pin removed, grub.cfg
# regenerated by the hook itself (no zz-update-grub runs after header_postinst.d).
exec > /out/s4-noheaders.log 2>&1
. /w/tests/lib.sh
base_setup
say "install linux-image 7.0.0-42 only"
kinst linux-image-7.0.0-42-generic
kstate 7.0.0-42-generic
grubstate
btusb-e3 status
say "now the headers"
kinst linux-headers-7.0.0-42-generic
kstate 7.0.0-42-generic
grubstate
initrdstate 7.0.0-42-generic
hooklog
